<script>
const helpSearch=document.getElementById('helpSearch'),helpItems=[...document.querySelectorAll('.help-item')],helpEmpty=document.getElementById('helpEmpty');let helpCategory='';
function filterHelp(){const q=helpSearch.value.trim().toLowerCase();let shown=0;helpItems.forEach(item=>{const visible=(!helpCategory||item.dataset.category===helpCategory)&&(!q||item.dataset.search.includes(q));item.style.display=visible?'':'none';if(visible)shown++});helpEmpty.style.display=shown?'none':'block'}
helpSearch.addEventListener('input',filterHelp);document.querySelectorAll('#helpFilters button').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('#helpFilters button').forEach(b=>b.classList.remove('active'));btn.classList.add('active');helpCategory=btn.dataset.category;filterHelp()}));filterHelp();
</script>
